package com.tripmateai.service;
import com.tripmateai.dto.request.trip.CreateTripRequest; import com.tripmateai.entity.*; import com.tripmateai.enums.TravelPreference; import com.tripmateai.exception.BadRequestException; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.impl.TripServiceImpl; import org.junit.jupiter.api.*; import org.mockito.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class TripServiceImplTest {
 @Mock TripRepository trips; @Mock DestinationRepository destinations; @Mock SavedTripRepository saved; @InjectMocks TripServiceImpl service; User user;
 @BeforeEach void setUp(){MockitoAnnotations.openMocks(this);user=new User();user.setId(1L);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new UserPrincipal(user),null,List.of()));}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @Test void createsTripForAuthenticatedOwner(){var d=new Destination();d.setId(4L);var request=new CreateTripRequest("Goa",4L,LocalDate.now().plusDays(2),LocalDate.now().plusDays(5),new BigDecimal("500"),2,Set.of(TravelPreference.BEACH)); when(destinations.findById(4L)).thenReturn(Optional.of(d)); when(trips.save(any())).thenAnswer(x->{var t=x.getArgument(0,Trip.class);t.setId(9L);return t;}); var response=service.createTrip(request);assertEquals(9L,response.id());verify(trips).save(argThat(t->t.getUser()==user&&t.getDestination()==d));}
 @Test void rejectsEndDateBeforeStart(){var r=new CreateTripRequest("Goa",4L,LocalDate.now().plusDays(5),LocalDate.now().plusDays(2),BigDecimal.ZERO,1,Set.of());assertThrows(BadRequestException.class,()->service.createTrip(r));verifyNoInteractions(destinations,trips);}
 @Test void preventsDuplicateSave(){var trip=new Trip();trip.setId(8L);when(trips.findById(8L)).thenReturn(Optional.of(trip));when(saved.existsByUserAndTrip(user,trip)).thenReturn(true);assertThrows(BadRequestException.class,()->service.saveTrip(8L));verify(saved,never()).save(any());}
}
